-- ============================================================================
-- Corrige a flag has_stock_control pra produtos que não estavam nos 48 IDs
-- fixos do seed original, mas que ainda assim só usam materiais genéricos
-- (sem estoque real) -- ex.: "NECESSAIRE SHELBY", que não está no
-- seed_bolsas.sql mas usa "Cursor", "Etiqueta em Couro / Cetim" etc.
--
-- Critério: desliga o controle de estoque de qualquer produto que NÃO tenha
-- nenhum material da ficha entre os 186 materiais reais sincronizados
-- (sync_materiais_atelie_bolsas.sql). Não mexe em produto que já usa pelo
-- menos um material real -- esses continuam com o valor que já tinham.
-- ============================================================================

update public.products p
set has_stock_control = false
where p.owner_id = '62f88a4b-a969-4f1a-8150-bfd21787abee'
  and exists (select 1 from public.product_materials pm where pm.product_id = p.id)
  and not exists (
    select 1
    from public.product_materials pm
    join public.materials m on m.id = pm.material_id
    where pm.product_id = p.id
      and m.name in (
    'ALÇA CADARÇO LARANJA (1,5 CM)', 'ALÇA CADARÇO PRETO (1,5 CM)', 'ALÇA CADARÇO VERDE MUSGO (1,5 CM)', 'ALÇA CHIQUE AZUL MARINHO (3 CM)',
